33: /**
34:  * Ibex simple system
35:  *
36:  * This is a basic system consisting of an ibex, a 1 MB sram for instruction/data
37:  * and a small memory mapped control module for outputting ASCII text and
38:  * controlling/halting the simulation from the software running on the ibex.
39:  *
40:  * It is designed to be used with verilator but should work with other
41:  * simulators, a small amount of work may be required to support the
42:  * simulator_ctrl module.
43:  */
44: 
45: module ibex_simple_system (
46:   input IO_CLK,
47:   input IO_RST_N
48: );
49: 
50:   parameter bit                 SecureIbex               = 1'b0;
51:   parameter int unsigned        LockstepOffset           = 1;
52:   parameter bit                 ICacheScramble           = 1'b0;
53:   parameter bit                 PMPEnable                = 1'b0;
54:   parameter int unsigned        PMPGranularity           = 0;
55:   parameter int unsigned        PMPNumRegions            = 4;
56:   parameter int unsigned        MHPMCounterNum           = 0;
57:   parameter int unsigned        MHPMCounterWidth         = 40;
58:   parameter bit                 RV32E                    = 1'b0;
59:   parameter ibex_pkg::rv32m_e   RV32M                    = `RV32M;
