1891:   if (DataIndTiming) begin : gen_dit
1892:     // SEC_CM: CORE.DATA_REG_SW.SCA
1893:     assign cpuctrlsts_part_wdata.data_ind_timing = cpuctrlsts_part_wdata_raw.data_ind_timing;
1894: 
1895:   end else begin : gen_no_dit
1896:     // tieoff for the unused bit
1897:     logic unused_dit;
1898:     assign unused_dit = cpuctrlsts_part_wdata_raw.data_ind_timing;
1899: 
1900:     // field will always read as zero if not configured
1901:     assign cpuctrlsts_part_wdata.data_ind_timing = 1'b0;
1902:   end
1903: 
1904:   assign data_ind_timing_o = cpuctrlsts_part_q.data_ind_timing;
1905: 
1906:   // Generate dummy instruction signals
1907:   if (DummyInstructions) begin : gen_dummy
1908:     // SEC_CM: CTRL_FLOW.UNPREDICTABLE
1909:     assign cpuctrlsts_part_wdata.dummy_instr_en   = cpuctrlsts_part_wdata_raw.dummy_instr_en;
