408:   assign div_change_sign = (div_sign_a ^ div_sign_b) & ~div_by_zero_q;
409:   assign rem_change_sign = div_sign_a;
410: 
411: 
412:   always_comb begin
413:     div_counter_d    = div_counter_q - 5'h1;
414:     op_remainder_d   = imd_val_q_i[0];
415:     op_quotient_d    = op_quotient_q;
416:     md_state_d       = md_state_q;
417:     op_numerator_d   = op_numerator_q;
418:     op_denominator_d = op_denominator_q;
419:     alu_operand_a_o  = {32'h0  , 1'b1};
420:     alu_operand_b_o  = {~op_b_i, 1'b1};
421:     div_valid        = 1'b0;
422:     div_hold         = 1'b0;
423:     div_by_zero_d    = div_by_zero_q;
424: 
425:     unique case (md_state_q)
426:       MD_IDLE: begin
427:         if (operator_i == MD_OP_DIV) begin
428:           // Check if the Denominator is 0
429:           // quotient for division by 0 is specified to be -1
430:           // Note with data-independent time option, the full divide operation will proceed as
431:           // normal and will naturally return -1
432:           op_remainder_d = '1;
433:           // SEC_CM: CORE.DATA_REG_SW.SCA
434:           md_state_d     = (!data_ind_timing_i && equal_to_zero_i) ? MD_FINISH : MD_ABS_A;
435:           // Record that this is a div by zero to stop the sign change at the end of the
436:           // division (in data_ind_timing mode).
437:           div_by_zero_d  = equal_to_zero_i;
438:         end else begin
439:           // Check if the Denominator is 0
440:           // remainder for division by 0 is specified to be the numerator (operand a)
441:           // Note with data-independent time option, the full divide operation will proceed as
442:           // normal and will naturally return operand a
443:           op_remainder_d = {2'b0, op_a_i};
444:           // SEC_CM: CORE.DATA_REG_SW.SCA
445:           md_state_d     = (!data_ind_timing_i && equal_to_zero_i) ? MD_FINISH : MD_ABS_A;
446:         end
447:         // 0 - B = 0 iff B == 0
448:         alu_operand_a_o  = {32'h0  , 1'b1};
449:         alu_operand_b_o  = {~op_b_i, 1'b1};
450:         div_counter_d    = 5'd31;
451:       end
452: 
453:       MD_ABS_A: begin
454:         // quotient
455:         op_quotient_d   = '0;
456:         // A abs value
457:         op_numerator_d  = div_sign_a ? alu_adder_i : op_a_i;
458:         md_state_d      = MD_ABS_B;
459:         div_counter_d   = 5'd31;
460:         // ABS(A) = 0 - A
461:         alu_operand_a_o = {32'h0  , 1'b1};
462:         alu_operand_b_o = {~op_a_i, 1'b1};
463:       end
464: 
465:       MD_ABS_B: begin
466:         // remainder
467:         op_remainder_d   = { 33'h0, op_numerator_q[31]};
468:         // B abs value
469:         op_denominator_d = div_sign_b ? alu_adder_i : op_b_i;
470:         md_state_d       = MD_COMP;
471:         div_counter_d    = 5'd31;
472:         // ABS(B) = 0 - B
473:         alu_operand_a_o  = {32'h0  , 1'b1};
474:         alu_operand_b_o  = {~op_b_i, 1'b1};
475:       end
476: 
477:       MD_COMP: begin
478:         op_remainder_d  = {1'b0, next_remainder[31:0], op_numerator_q[div_counter_d]};
479:         op_quotient_d   = next_quotient[31:0];
480:         md_state_d      = (div_counter_q == 5'd1) ? MD_LAST : MD_COMP;
481:         // Division
482:         alu_operand_a_o = {imd_val_q_i[0][31:0], 1'b1}; // it contains the remainder
483:         alu_operand_b_o = {~op_denominator_q[31:0], 1'b1};  // -denominator two's compliment
484:       end
485: 
486:       MD_LAST: begin
487:         if (operator_i == MD_OP_DIV) begin
488:           // this time we save the quotient in op_remainder_d (i.e. imd_val_q_i[0]) since
489:           // we do not need anymore the remainder
490:           op_remainder_d = {1'b0, next_quotient};
491:         end else begin
492:           // this time we do not save the quotient anymore since we need only the remainder
493:           op_remainder_d = {2'b0, next_remainder[31:0]};
494:         end
495:         // Division
496:         alu_operand_a_o  = {imd_val_q_i[0][31:0], 1'b1}; // it contains the remainder
497:         alu_operand_b_o  = {~op_denominator_q[31:0], 1'b1};  // -denominator two's compliment
498: 
499:         md_state_d = MD_CHANGE_SIGN;
500:       end
501: 
502:       MD_CHANGE_SIGN: begin
503:         md_state_d  = MD_FINISH;
504:         if (operator_i == MD_OP_DIV) begin
505:           op_remainder_d = (div_change_sign) ? {2'h0, alu_adder_i} : imd_val_q_i[0];
506:         end else begin
507:           op_remainder_d = (rem_change_sign) ? {2'h0, alu_adder_i} : imd_val_q_i[0];
508:         end
509:         // ABS(Quotient) = 0 - Quotient (or Remainder)
510:         alu_operand_a_o  = {32'h0  , 1'b1};
511:         alu_operand_b_o  = {~imd_val_q_i[0][31:0], 1'b1};
512:       end
513: 
514:       MD_FINISH: begin
515:         // Hold result until ID stage is ready to accept it
516:         // Note no state transition will occur if div_hold is set
517:         md_state_d = MD_IDLE;
518:         div_hold   = ~multdiv_ready_id_i;
519:         div_valid   = 1'b1;
520:       end
521: 
522:       default: begin
523:         md_state_d = MD_IDLE;
524:       end
525:     endcase // md_state_q
526:   end
527: 
528: 
529:   assign valid_o = mult_valid | div_valid;

