443:           addr_update   = 1'b1;
444:           pmp_err_d     = 1'b0;
445:           lsu_err_d     = 1'b0;
446:           perf_load_o   = 1'b0;
447:           lsu_go        = 1'b1;         // decision to move forward with a request
448:           ls_fsm_ns     = IDLE;
449:         end else if ((BaseIsa == BaseIsaRV32IorCHERIoT) & (cheriot_enable_i == IbexMuBiOn) &
450:             cpu_req_valid & lsu_is_cap_i) begin
451:           // normal cap access case
452:           data_req_o     = 1'b1;
453:           cheriot_err_d  = 1'b0;
454:           pmp_err_d      = data_pmp_err_i;
455:           lsu_err_d      = 1'b0;
456:           perf_load_o    = ~lsu_we_i;
457:           perf_store_o   = lsu_we_i;
458:           lsu_go         = 1'b1;         // decision to move forward with a request
459:           lsu_go_goodcap = 1'b1;
460: 
461:           if (data_gnt_i) begin
462:             ctrl_update = 1'b1;
463:             addr_update = 1'b1;
464:             ls_fsm_ns   = CTX_WAIT_GNT2;
465:           end else begin
466:             ls_fsm_ns   = CTX_WAIT_GNT1;
467:           end
468:         end else if (cpu_req_valid) begin
469:           // normal data access case
470:           data_req_o    = 1'b1;
471:           cheriot_err_d = 1'b0;
472:           pmp_err_d     = data_pmp_err_i;
473:           lsu_err_d     = 1'b0;
474:           perf_load_o   = ~lsu_we_i;
475:           perf_store_o  = lsu_we_i;
476:           lsu_go        = 1'b1;         // decision to move forward with a request
477: 
478:           if (data_gnt_i) begin
479:             ctrl_update         = 1'b1;
480:             addr_update         = 1'b1;
481:             handle_misaligned_d = split_misaligned_access;
482:             ls_fsm_ns           = split_misaligned_access ? WAIT_RVALID_MIS : IDLE;
483:           end else begin
484:             ls_fsm_ns           = split_misaligned_access ? WAIT_GNT_MIS    : WAIT_GNT;
485:           end
486:         end

533:       WAIT_GNT: begin
534:         // tell ID/EX stage to update the address
535:         addr_incr_req_o = handle_misaligned_q;
536:         data_req_o      = 1'b1;
537:         if (data_gnt_i || pmp_err_q) begin
538:           ctrl_update         = 1'b1;
539:           // Update the address, unless there was an error
540:           addr_update         = ~lsu_err_q;
541:           ls_fsm_ns           = IDLE;
542:           handle_misaligned_d = 1'b0;
543:         end
544:       end
